import json

R = []  # list of [pattern, repl]


def idx(f, r):  # file 0-7, rank 1-8
    return (8 - r) * 8 + f


def fr(i):
    return i % 8, 8 - i // 8


def name(i):
    f, r = fr(i)
    return "abcdefgh"[f] + str(r)


# ---------------- Phase 1: normalise ----------------
for d in range(8, 0, -1):
    R.append([r"%d(?=[^ ]* w )" % d, "." * d])
R.append([r"/", ""])
for m in range(16):
    full = "".join(c if m >> k & 1 else "" for k, c in enumerate("KQkq"))
    fixed = "".join(c if m >> k & 1 else "-" for k, c in enumerate("KQkq"))
    src = full if full else "-"
    R.append([r"^(\S+) w %s (\S+) .*$" % src, r"S\g<1> %s \g<2>" % fixed])

# line format: S + 64 board + " " + 4 castle chars + " " + ep


# ---------------- Phase 2: move generation ----------------
def move_rule(conds, changes, prefix="C", castle_clear=(), ep="-", ep_req=None):
    """conds: idx->regex class; changes: idx->new literal char."""
    pat = r"(?m)^S"
    rep = []
    g = 0
    i = 0
    while i < 64:
        if i in conds or i in changes:
            c = conds.get(i, ".")
            if i in changes:
                pat += c
                rep.append(changes[i])
            else:
                g += 1
                pat += "(" + c + ")"
                rep.append(r"\g<%d>" % g)
            i += 1
        else:
            j = i
            while j < 64 and j not in conds and j not in changes:
                j += 1
            g += 1
            pat += "(.{%d})" % (j - i)
            rep.append(r"\g<%d>" % g)
            i = j
    pat += r" (.)(.)(.)(.) "
    cg = []
    for k in range(4):
        g += 1
        cg.append(r"\g<%d>" % g)
    pat += re_escape(ep_req) if ep_req else r"\S+"
    pat += "$"
    cast = "".join("-" if k in castle_clear else cg[k] for k in range(4))
    repl = "\\g<0>\n" + prefix + "".join(rep) + " " + cast + " " + ep
    R.append([pat, repl])


def re_escape(s):
    return s.replace("-", r"\-")


def castle_clear_for(frm, to):
    cl = set()
    if frm in (60, 63):
        cl.add(0)
    if frm in (60, 56):
        cl.add(1)
    if to == 7:
        cl.add(2)
    if to == 0:
        cl.add(3)
    return cl


EMPTY = r"\."
TARGET = r"[.a-z]"
BLACK = r"[a-z]"

ORTH = [(1, 0), (-1, 0), (0, 1), (0, -1)]
DIAG = [(1, 1), (1, -1), (-1, 1), (-1, -1)]
KN = [(1, 2), (2, 1), (-1, 2), (-2, 1), (1, -2), (2, -1), (-1, -2), (-2, -1)]


def on(f, r):
    return 0 <= f < 8 and 1 <= r <= 8


for s in range(64):
    f, r = fr(s)
    # sliders
    for piece, dirs in (("R", ORTH), ("B", DIAG), ("Q", ORTH + DIAG)):
        for df, dr in dirs:
            path = []
            for d in range(1, 8):
                nf, nr = f + df * d, r + dr * d
                if not on(nf, nr):
                    break
                t = idx(nf, nr)
                conds = {s: piece, t: TARGET}
                for p in path:
                    conds[p] = EMPTY
                move_rule(conds, {s: ".", t: piece}, castle_clear=castle_clear_for(s, t))
                path.append(t)
    # knight
    for df, dr in KN:
        if on(f + df, r + dr):
            t = idx(f + df, r + dr)
            move_rule({s: "N", t: TARGET}, {s: ".", t: "N"}, castle_clear=castle_clear_for(s, t))
    # king
    for df, dr in ORTH + DIAG:
        if on(f + df, r + dr):
            t = idx(f + df, r + dr)
            move_rule({s: "K", t: TARGET}, {s: ".", t: "K"}, castle_clear={0, 1} | castle_clear_for(s, t))
    # pawns
    if 2 <= r <= 7:
        t = idx(f, r + 1)
        np = "Q" if r + 1 == 8 else "P"
        move_rule({s: "P", t: EMPTY}, {s: ".", t: np})
        if r == 2:
            t2 = idx(f, 4)
            move_rule({s: "P", t: EMPTY, t2: EMPTY}, {s: ".", t2: "P"}, ep=name(t))
        for df in (-1, 1):
            if on(f + df, r + 1):
                t = idx(f + df, r + 1)
                move_rule({s: "P", t: BLACK}, {s: ".", t: np}, castle_clear=castle_clear_for(s, t))
        if r == 5:
            for df in (-1, 1):
                if on(f + df, 6):
                    t = idx(f + df, 6)
                    cap = idx(f + df, 5)
                    move_rule({s: "P", t: EMPTY, cap: "p"}, {s: ".", t: "P", cap: "."},
                              ep_req=name(t))

# castling (temporary multi-king representation)
R.append([r"(?m)^S(.{60})K\.\.R K(.{3}) \S+$",
          "\\g<0>\nD\\g<1>KKKR -\\g<2> -"])
R.append([r"(?m)^S(.{56})R\.\.\.K(.{3}) (.)(.{2}) \S+$",
          "\\g<0>\nE\\g<1>R.KKK\\g<2> \\g<3>-\\g<4> -"])


# ---------------- Phase 3: legality ----------------
def posre(conds):
    out = ""
    last = 0
    for i in sorted(conds):
        if i > last:
            out += ".{%d}" % (i - last)
        out += conds[i]
        last = i + 1
    return out


for k in range(64):
    f, r = fr(k)
    pats = []
    # pawns (black pawns attack downward)
    for df in (-1, 1):
        if on(f + df, r + 1):
            pats.append({k: "K", idx(f + df, r + 1): "p"})
    for df, dr in KN:
        if on(f + df, r + dr):
            pats.append({k: "K", idx(f + df, r + dr): "n"})
    for df, dr in ORTH + DIAG:
        if on(f + df, r + dr):
            pats.append({k: "K", idx(f + df, r + dr): "k"})
    for dirs, cls in ((ORTH, "[rq]"), (DIAG, "[bq]")):
        for df, dr in dirs:
            path = []
            for d in range(1, 8):
                nf, nr = f + df * d, r + dr * d
                if not on(nf, nr):
                    break
                t = idx(nf, nr)
                c = {k: "K", t: cls}
                for p in path:
                    c[p] = EMPTY
                pats.append(c)
                path.append(t)
    alts = "|".join(posre(c) for c in pats)
    R.append([r"(?m)^[CDE](?=%s)" % ("(?:" + alts + ")"), "X"])

R.append([r"\nX[^\n]*", ""])
R.append([r"^S[^\n]*\n?", ""])
R.append([r"(?m)^D(.{60})KKKR", r"C\g<1>.RK."])
R.append([r"(?m)^E(.{56})R\.KKK", r"C\g<1>..KR."])

# ---------------- Phase 4: output ----------------
R.append([r"(?m)^C" + "(.{8})" * 8 + " ", "/".join(r"\g<%d>" % i for i in range(1, 9)) + " "])
for d in range(8, 0, -1):
    R.append([r"\.{%d}" % d, str(d)])
for m in range(16):
    full = "".join(c if m >> k & 1 else "" for k, c in enumerate("KQkq"))
    fixed = "".join(c if m >> k & 1 else "-" for k, c in enumerate("KQkq"))
    R.append([r"(?m)^(\S+) %s (\S+)$" % re_escape(fixed),
              r"\g<1> b %s \g<2> 0 0" % (full if full else "-")])

json.dump(R, open("re.json", "w"))
print(len(R), "rules")
